"use client";

import * as React from "react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import styles from "../styles/stepper.module.css";

export interface StepperStep {
  /** Step title */
  title: string;
  /** Optional supporting line */
  description?: string;
}

export interface StepperProps {
  /** Steps to render */
  steps?: StepperStep[];
  /** Controlled active step index (0-based; steps.length means all complete) */
  activeStep?: number;
  /** Initial active step when uncontrolled */
  defaultStep?: number;
  /** Called with the next active step index */
  onStepChange?: (step: number) => void;
  /** Layout direction */
  orientation?: "horizontal" | "vertical";
  /** Size preset */
  size?: "sm" | "md" | "lg";
  /** Accent color of completed steps and the connector fill */
  accentColor?: string;
  /** Show step descriptions */
  showDescriptions?: boolean;
  /** Let users jump back to completed steps by clicking them */
  clickable?: boolean;
  /** Show the Back / Next demo buttons */
  showControls?: boolean;
  /** Label of the Next button */
  nextLabel?: string;
  /** Label of the Back button */
  backLabel?: string;
  /** Optional className merged onto the root */
  className?: string;
  /** Optional inline styles merged onto the root */
  style?: React.CSSProperties;
}

const DEFAULT_STEPS: StepperStep[] = [
  { title: "Account", description: "Email and password" },
  { title: "Profile", description: "Name and avatar" },
  { title: "Workspace", description: "Invite your team" },
  { title: "Launch", description: "Review and go live" },
];

export function Stepper({
  steps = DEFAULT_STEPS,
  activeStep,
  defaultStep = 1,
  onStepChange,
  orientation = "horizontal",
  size = "md",
  accentColor = "#6366f1",
  showDescriptions = true,
  clickable = true,
  showControls = true,
  nextLabel = "Next",
  backLabel = "Back",
  className = "",
  style,
}: StepperProps) {
  const reduce = useReducedMotion();
  const [inner, setInner] = React.useState(defaultStep);
  const controlled = activeStep !== undefined;
  const count = steps.length;
  const current = Math.min(count, Math.max(0, Math.round(controlled ? activeStep : inner)));
  const done = current >= count;

  const go = (n: number) => {
    const next = Math.min(count, Math.max(0, n));
    if (next === current) return;
    if (!controlled) setInner(next);
    onStepChange?.(next);
  };

  const spring = reduce ? { duration: 0 } : { type: "spring" as const, stiffness: 420, damping: 30 };

  return (
    <div
      className={`${styles.root} ${className}`.trim()}
      data-orientation={orientation}
      data-size={size}
      style={{ "--mf-stp-accent": accentColor, ...style } as React.CSSProperties}
    >
      <ol className={styles.list} aria-label="Progress">
        {steps.map((s, i) => {
          const state = i < current ? "complete" : i === current ? "current" : "upcoming";
          const canClick = clickable && i < current;
          const dotInner = (
            <AnimatePresence initial={false}>
              {state === "complete" ? (
                <motion.svg
                  key="check"
                  aria-hidden="true"
                  width="16"
                  height="16"
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="3"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  initial={{ scale: reduce ? 1 : 0.4, opacity: 0 }}
                  animate={{ scale: 1, opacity: 1 }}
                  exit={{ scale: reduce ? 1 : 0.4, opacity: 0 }}
                  transition={spring}
                >
                  <motion.path d="M5 12.5 10 17l9-10" initial={{ pathLength: reduce ? 1 : 0 }} animate={{ pathLength: 1 }} transition={{ duration: reduce ? 0 : 0.3, delay: reduce ? 0 : 0.08 }} />
                </motion.svg>
              ) : (
                <motion.span key="num" aria-hidden="true" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} transition={{ duration: reduce ? 0 : 0.15 }}>
                  {i + 1}
                </motion.span>
              )}
            </AnimatePresence>
          );
          return (
            <li key={`${s.title}-${i}`} className={styles.step} data-state={state} aria-current={state === "current" ? "step" : undefined}>
              <div className={styles.rail}>
                {canClick ? (
                  <button type="button" className={styles.dot} onClick={() => go(i)} aria-label={`Go back to step ${i + 1}: ${s.title}`}>
                    {dotInner}
                  </button>
                ) : (
                  <span className={styles.dot}>{dotInner}</span>
                )}
                {i < count - 1 && (
                  <span aria-hidden="true" className={styles.line}>
                    <span className={styles.fill} data-filled={i < current ? "" : undefined} />
                  </span>
                )}
              </div>
              <div className={styles.text}>
                <span className={styles.title}>
                  {s.title}
                  <span className={styles.srOnly}>{state === "complete" ? " (completed)" : state === "current" ? " (current step)" : ""}</span>
                </span>
                {showDescriptions && s.description && <span className={styles.desc}>{s.description}</span>}
              </div>
            </li>
          );
        })}
      </ol>
      {showControls && (
        <div className={styles.controls}>
          <p className={styles.status} aria-live="polite">
            {done ? "All steps complete" : `Step ${current + 1} of ${count}: ${steps[current]?.title ?? ""}`}
          </p>
          <div className={styles.buttons}>
            <button type="button" className={styles.secondary} disabled={current === 0} onClick={() => go(current - 1)}>
              {backLabel}
            </button>
            <button type="button" className={styles.primary} onClick={() => go(done ? 0 : current + 1)}>
              {done ? "Start over" : current === count - 1 ? "Finish" : nextLabel}
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

.root {
  --mf-stp-dot: 2.25rem;
  --mf-stp-fs: 0.875rem;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
  width: 100%;
  max-width: 40rem;
  color: var(--mf-fg, #f4f4f6);
  font-size: var(--mf-stp-fs);
}

.root[data-size="sm"] {
  --mf-stp-dot: 1.875rem;
  --mf-stp-fs: 0.8125rem;
}

.root[data-size="lg"] {
  --mf-stp-dot: 2.75rem;
  --mf-stp-fs: 0.9375rem;
}

.root[data-orientation="vertical"] {
  max-width: 24rem;
}

.list {
  display: flex;
  margin: 0;
  padding: 0;
  list-style: none;
}

.root[data-orientation="vertical"] .list {
  flex-direction: column;
}

.step {
  display: flex;
  flex-direction: column;
  gap: 0.625rem;
  flex: 1 1 0;
  min-width: 0;
}

.step:last-child {
  flex: 0 0 auto;
}

.root[data-orientation="vertical"] .step {
  flex-direction: row;
  gap: 0.875rem;
}

.rail {
  display: flex;
  align-items: center;
}

.root[data-orientation="vertical"] .rail {
  flex-direction: column;
}

.dot {
  display: grid;
  place-items: center;
  flex-shrink: 0;
  width: var(--mf-stp-dot);
  height: var(--mf-stp-dot);
  padding: 0;
  border-radius: 999px;
  border: 2px solid var(--mf-border, #2e2e38);
  background-color: var(--mf-surface, #141419);
  color: var(--mf-muted, #a1a1aa);
  font: inherit;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  transition: background-color 220ms ease, border-color 220ms ease, color 220ms ease, box-shadow 260ms ease;
}

.dot > * {
  grid-area: 1 / 1;
}

button.dot {
  cursor: pointer;
}

button.dot:hover {
  filter: brightness(1.12);
}

.dot:focus-visible {
  outline: 2px solid var(--mf-fg, #e4e4e7);
  outline-offset: 2px;
}

.step[data-state="current"] .dot {
  border-color: var(--mf-stp-accent, #6366f1);
  color: var(--mf-fg, #f4f4f6);
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--mf-stp-accent, #6366f1) 22%, transparent);
}

.step[data-state="complete"] .dot {
  border-color: var(--mf-stp-accent, #6366f1);
  background-color: var(--mf-stp-accent, #6366f1);
  color: #ffffff;
}

.line {
  position: relative;
  flex: 1;
  height: 2px;
  margin: 0 0.625rem;
  border-radius: 2px;
  overflow: hidden;
  background-color: var(--mf-border, #2e2e38);
}

.root[data-orientation="vertical"] .line {
  width: 2px;
  height: auto;
  min-height: 2rem;
  margin: 0.375rem 0;
}

.fill {
  position: absolute;
  inset: 0;
  background-color: var(--mf-stp-accent, #6366f1);
  transform: scaleX(0);
  transform-origin: left center;
  transition: transform 420ms cubic-bezier(0.65, 0, 0.35, 1);
}

.root[data-orientation="vertical"] .fill {
  transform: scaleY(0);
  transform-origin: center top;
}

.fill[data-filled],
.root[data-orientation="vertical"] .fill[data-filled] {
  transform: none;
}

.text {
  display: flex;
  flex-direction: column;
  gap: 0.125rem;
  min-width: 0;
  padding-right: 0.75rem;
}

.root[data-orientation="vertical"] .text {
  padding: calc((var(--mf-stp-dot) - 1.25rem) / 2) 0 1.25rem;
}

.title {
  font-weight: 600;
  line-height: 1.25rem;
  color: var(--mf-muted, #a1a1aa);
  transition: color 200ms ease;
}

.step[data-state="current"] .title,
.step[data-state="complete"] .title {
  color: var(--mf-fg, #f4f4f6);
}

.desc {
  font-size: 0.8125rem;
  line-height: 1.4;
  color: var(--mf-subtle, #71717a);
}

.controls {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  padding: 0.875rem 1rem;
  border-radius: 0.75rem;
  border: 1px solid var(--mf-border, #2e2e38);
  background-color: var(--mf-surface, #141419);
}

.status {
  margin: 0;
  color: var(--mf-muted, #a1a1aa);
}

.buttons {
  display: flex;
  gap: 0.5rem;
}

.primary,
.secondary {
  height: 2.25rem;
  padding: 0 1rem;
  border-radius: 0.5rem;
  font: inherit;
  font-weight: 500;
  cursor: pointer;
  transition: background-color 150ms ease, border-color 150ms ease, opacity 150ms ease, transform 120ms ease;
}

.primary {
  border: 1px solid transparent;
  background-color: var(--mf-stp-accent, #6366f1);
  color: #ffffff;
}

.primary:hover {
  filter: brightness(1.08);
}

.secondary {
  border: 1px solid var(--mf-border, #2e2e38);
  background-color: transparent;
  color: var(--mf-fg, #f4f4f6);
}

.secondary:hover:not(:disabled) {
  border-color: var(--mf-border-strong, #52525b);
}

.primary:active:not(:disabled),
.secondary:active:not(:disabled) {
  transform: scale(0.97);
}

.secondary:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.primary:focus-visible,
.secondary:focus-visible {
  outline: 2px solid var(--mf-fg, #e4e4e7);
  outline-offset: 2px;
}

.srOnly {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

@media (prefers-reduced-motion: reduce) {
  .dot,
  .fill,
  .title,
  .primary,
  .secondary {
    transition: none;
  }
}

