"use client";

import { Fragment, useState } from "react";

const STEPS = ["Account", "Profile", "Workspace", "Launch"];

export function StepperTailwind() {
  const [step, setStep] = useState(1);
  return (
    <div className="w-full max-w-xl space-y-6 text-sm">
      <ol aria-label="Progress" className="flex items-center">
        {STEPS.map((title, i) => (
          <Fragment key={title}>
            <li aria-current={i === step ? "step" : undefined} className="flex items-center gap-2">
              <span className={`grid size-9 place-items-center rounded-full border-2 font-semibold transition-colors ${i < step ? "border-indigo-500 bg-indigo-500 text-white" : i === step ? "border-indigo-500 text-zinc-100 ring-4 ring-indigo-500/20" : "border-zinc-800 text-zinc-400"}`}>{i < step ? "\u2713" : i + 1}</span>
              <span className={i <= step ? "font-semibold text-zinc-100" : "text-zinc-400"}>{title}</span>
            </li>
            {i < STEPS.length - 1 && (
              <li aria-hidden className="mx-3 h-0.5 flex-1 overflow-hidden rounded bg-zinc-800">
                <span className={`block h-full origin-left bg-indigo-500 transition-transform duration-500 ${i < step ? "scale-x-100" : "scale-x-0"}`} />
              </li>
            )}
          </Fragment>
        ))}
      </ol>
      <div className="flex justify-end gap-2">
        <button disabled={step === 0} onClick={() => setStep(step - 1)} className="h-9 rounded-lg border border-zinc-800 px-4 text-zinc-100 disabled:opacity-40">Back</button>
        <button onClick={() => setStep(Math.min(STEPS.length, step + 1))} className="h-9 rounded-lg bg-indigo-500 px-4 font-medium text-white">Next</button>
      </div>
    </div>
  );
}
